mapper.select:
select ROVIH.FILE_NAME fileName, ROVIH.FILE_PATH filePath, ROVIH.PORTFOLIO_ID portfolioId, ROVIH.PORTFOLIO_NAME portfolioName, ROVIH.START_TIME startTime, ROVIH.END_TIME endTime, ROVIH.VALDATE valdate, ROVIH.IMPDATE impdate, ROVIH.IMPORT_TYPE importType, ROVIH.ERROR_CODE errorCode from RSK_OUT_VALTBL_IMPORT_HIS ROVIH left join PTL_PORTFOLIO ptp on ptp.PORTFOLIO_ID = ROVIH.PORTFOLIO_ID
AND ROVIH.IMPORT_TYPE = #{importType,jdbcType=VARCHAR}
and to_char(ROVIH.IMPDATE,'yyyy-MM-dd') = #{searchDate,jdbcType=VARCHAR}
and to_char(ROVIH.END_TIME,'yyyy-MM-dd') >= #{searchDate,jdbcType=VARCHAR}
and (exists (select 1 from sys_department s where s.dept_code = ptp.create_dept and s.institution_code = #{orgCode} ) OR ROVIH.PORTFOLIO_ID IS NULL)
ORDER BY ROVIH.START_TIME DESC

SELECT DISTINCT
A.PORTFOLIO_ID PORTFOLIO_ID,
A.PORTFOLIO_NAME PORTFOLIO_NAME
FROM PTL_PORTFOLIO A
LEFT JOIN PA_PTL_PORTFOLIO B
ON A.PORTFOLIO_ID = B.PORTFOLIO_ID


        A.PORTFOLIO_NAME = #{search}


        AND A.PORTFOLIO_ID = #{initValue}


        AND (A.PORTFOLIO_TYPE = #{portfolioType}
        OR  A.PORTFOLIO_TYPE = #{portfolioType2})



        and exists
        (select 1
        from sys_department s
        where s.dept_code = A.create_dept
        and s.institution_code = #{orgCode}
        )

SELECT count(1)
 FROM SYS_DEPARTMENT
where SYS_DEPARTMENT.INSTITUTION_CODE = #{orgCode}

select FILE_NAME fileName, FILE_PATH filePath, PORTFOLIO_ID portfolioId, PORTFOLIO_NAME portfolioName, START_TIME startTime, END_TIME endTime, VALDATE valdate, IMPDATE impdate, IMPORT_TYPE importType, ERROR_CODE errorCode from VALTBL_IMPORT_HIS_TRACE
FILE_NAME = #{fileName,jdbcType=VARCHAR} AND PORTFOLIO_NAME = #{portfolioName,jdbcType=VARCHAR} and VALDATE = #{valdate,jdbcType=VARCHAR}
ORDER BY START_TIME DESC
